#pragma once

// MOS (moment-of-symmetry) scale math: a port of the mos-explorer (SPEC §3.2, §4.2).
//
// Every function here reproduces the corresponding JavaScript function in mos-explorer's index.html (or mos-calc.js
// where noted) exactly, including its rounding thresholds, tie-breaking and quirks, because tests/tuning/fixtures/
// mos_*.json (generated by running the original JS under Node) are the acceptance criterion. Where the JS reads
// global UI state, the C++ takes it as a parameter:
//   S.period          -> `period` (cents)
//   S.selected        -> `const RegionHint* sel` (only chainSafeGenerator reads it; nullptr = no selection)
//   S.octaveStretch   -> `octaveStretch` (cents added to the 1200-cent octave)
// Suspected JS bugs are listed in docs/QUESTIONS.md, not fixed here.
//
// These functions allocate (they return vectors/strings) and are for the UI/document side. The audio-rate path uses
// MosLinearTable (mos_regions.h) and Mos::centsOfDegree (mos_tuning.h), which are allocation-free.

#include <array>
#include <cstdint>
#include <optional>
#include <span>
#include <string>
#include <string_view>
#include <vector>

namespace pq::tuning {

// A MOS family "nL ns", e.g. {5, 2} is the diatonic 5L 2s. Counts are for the whole scale (the JS key).
struct MosKey {
  int32_t nL = 0;
  int32_t nS = 0;
  constexpr int32_t size() const noexcept { return nL + nS; }
  friend constexpr bool operator==(const MosKey&, const MosKey&) noexcept = default;
};

// "5L_2s" (the JS key form).
std::string mosKeyString(MosKey k);
// "5L 2s" (mosDisplayLabel).
std::string mosDisplayLabel(MosKey k);
// First "<digits>L_<digits>s" in the text (the JS regex /(\d+)L_(\d+)s/), or nullopt.
std::optional<MosKey> parseMosKey(std::string_view text);

// Stern–Brocot tree navigation (findParentMOS / getChildMOSes / isDescendantMOS / mos-calc getAncestorChain).
std::optional<MosKey> findParentMos(int32_t nL, int32_t nS) noexcept;  // RT-safe
std::array<MosKey, 2> childMoses(MosKey k) noexcept;                   // RT-safe
bool isDescendantMos(MosKey child, MosKey ancestor) noexcept;           // RT-safe; ≤ 30 levels like the JS
std::vector<MosKey> ancestorChain(MosKey k);                            // k first, then parents (≤ 50)

// The selected region, as far as chainSafeGenerator cares (S.selected).
struct RegionHint {
  int32_t perPeriodSize = 0;
  double lowCents = 0.0;
  double highCents = 0.0;
};

// Sorted pitches (cents from the tonic, in [0, period)) and the steps between them; steps[n−1] wraps to the period.
// L and s are the largest and smallest step rounded to 0.01 cents (the JS rounds before comparing).
struct MosScale {
  std::vector<double> pitches;
  std::vector<double> steps;
  double L = 0.0;
  double s = 0.0;
};

// chainSafeGen: at a degenerate generator (some chain pitch lands on the period) nudge by 1e-7 cents toward the
// selected region's interior, or toward the side where the chain is a true MOS.
double chainSafeGenerator(double genCents, int32_t n, double period, const RegionHint* sel = nullptr);

// buildMOSScale: an n-note chain of genCents, reduced into the period and sorted.
MosScale buildMosScale(double genCents, int32_t n, double period, const RegionHint* sel = nullptr);

// computeHardness (index.html): L, s (0.01-rounded) and L/s; s = 0 and ratio = ∞ for a collapsed scale.
// str is ratio.toFixed(2), "1.00" for an equalized scale, or "∞:1".
struct Hardness {
  double L = 0.0;
  double s = 0.0;
  double ratio = 1.0;
  std::string str;
};
Hardness computeHardness(double genCents, int32_t mosSize, double period);

// getGeneratorChain: for each sorted degree, its position in the generator chain.
std::vector<int32_t> generatorChain(double genCents, int32_t n, double period, const RegionHint* sel = nullptr);

// isBrightGenerator: rooting at chain position 0 gives the brightest mode.
bool isBrightGenerator(double genCents, int32_t n, double period, const RegionHint* sel = nullptr);

// computeUDP: "u|d" (up|down generators), nullopt if n < 2.
std::optional<std::string> computeUdp(double genCents, int32_t n, int32_t modeRotation, double period,
                                      const RegionHint* sel = nullptr);

// gmnGenerator: the generator that orders the genchain for GMN (fifth-sized preferred, else the smaller).
double gmnGenerator(double genCents, double period) noexcept;  // RT-safe
// computeGMN: 1-based genchain mode number (Kite Giedraitis), nullopt if n < 2.
std::optional<int32_t> computeGmn(double genCents, int32_t n, int32_t modeRotation, double period,
                                  const RegionHint* sel = nullptr);
// gmnLabel: "Mode 4".
std::string gmnLabel(int32_t gmn);

// formatModmosAlterations: "+4 -6 -1.5×9" (tonic-relative 1-based degrees, chroma multiples).
std::string formatModmosAlterations(std::span<const double> modmos);
// hasModmos: any alteration larger than 0.01 chroma.
bool hasModmos(std::span<const double> modmos) noexcept;  // RT-safe

// computeStepPattern: "LLsLLLs" for the rotated scale.
std::string computeStepPattern(double genCents, int32_t n, int32_t modeRotation, double period,
                               const RegionHint* sel = nullptr);

// transferModeRotation: carry a mode across a MOS change by keeping the root's genchain position (same size) or its
// relative brightness (different size). Rotation is a double because the JS accepts any number; anything that is
// not an integer in [0, oldN) gives 0, as do n < 2.
int32_t transferModeRotation(double oldGenCents, int32_t oldN, double oldRotation, double newGenCents, int32_t newN,
                             double period, const RegionHint* sel = nullptr);

// rotateByGenerator: the rotation one generator up (direction +1) or down (−1) the chain; −1 if not found.
int32_t rotateByGenerator(double genCents, int32_t n, int32_t currentRotation, int32_t direction, double period,
                          const RegionHint* sel = nullptr);

// rotateMOSScale: re-root at sorted degree `rotation` (0 ≤ rotation < n). Rotation 0 returns the scale unchanged;
// otherwise s is 0 when every step rounds equal (a JS quirk kept for fidelity; buildMosScale uses s = L there).
MosScale rotateMosScale(const MosScale& scale, int32_t rotation, double period);

// applyMODMOS: degree i is moved by modmos[i] chromas (chroma = L − s), reduced into the period, re-sorted.
// alts[j] is the cents offset applied to the note now at j, origDegs[j] the degree it came from. With an empty
// modmos the scale is returned as is and alts/origDegs are empty (the JS returns the input object).
struct ModmosScale {
  std::vector<double> pitches;
  std::vector<double> steps;
  double L = 0.0;
  double s = 0.0;
  std::vector<double> alts;
  std::vector<int32_t> origDegs;
};
ModmosScale applyModmos(const MosScale& scale, std::span<const double> modmos, double period);

// getRotationDegreeMap: for each degree of the rotated scale, the unrotated degree it is.
std::vector<int32_t> rotationDegreeMap(double genCents, int32_t n, int32_t rotation, double period,
                                       const RegionHint* sel = nullptr);

// handleModeButton without the UI: the new rotation and the MODMOS alterations carried to the degrees they were on.
enum class ModeAction : uint8_t { StepUp, StepDown, GenUp, GenDown };
struct ModeChange {
  int32_t rotation = 0;
  std::vector<double> modmos;
};
ModeChange applyModeAction(ModeAction action, double genCents, int32_t n, int32_t rotation,
                           std::span<const double> modmos, double period, const RegionHint* sel = nullptr);

// buildGenSequenceScale: chain of a repeating generator sequence (seq[0], seq[1], … seq[k−1], seq[0], …).
MosScale buildGenSequenceScale(std::span<const double> genSequence, int32_t n, double period);
// updateGenSequenceEntry: set seq[idx], taking the difference from the next entry (kept ≥ 1 cent). No-op if k < 2.
void updateGenSequenceEntry(std::vector<double>& genSequence, size_t idx, double newCents);

// Octave stretch: pure cents scaled so the octave becomes 1200 + octaveStretch cents. RT-safe.
inline double stretchedOctave(double octaveStretch) noexcept { return 1200.0 + octaveStretch; }
inline double stretchCents(double pureCents, double octaveStretch) noexcept {
  return pureCents * stretchedOctave(octaveStretch) / 1200.0;
}

// Everything that defines a MOS tuning's pitches (the S fields buildFullScale reads).
struct MosParams {
  double generator = 696.0;           // cents (S.generatorCents)
  int32_t n = 7;                      // notes per period (S.selected.perPeriodSize)
  double period = 1200.0;             // cents
  int32_t periodsPerEquave = 1;       // getPeriodRepetitions(): round(viewLimit / period)
  int32_t rotation = 0;               // mode rotation, 0 ≤ rotation < n
  std::vector<double> modmos;         // alterations in chromas per degree (may be shorter than n)
  std::vector<double> genSequence;    // non-empty: generator sequence instead of a single generator
  double octaveStretch = 0.0;         // cents added to the 1200-cent octave
  std::optional<RegionHint> region;   // the selected region (affects only degenerate generators)
};

// getPeriodRepetitions.
int32_t periodRepetitions(double viewLimit, double period) noexcept;  // RT-safe

// buildFullScale: the rotated (and MODMOS-altered) scale repeated over the equave. size = n · periodsPerEquave,
// equaveCents = period · periodsPerEquave (both unstretched).
struct FullScale {
  std::vector<double> pitches;
  int32_t size = 0;
  double equaveCents = 0.0;
};
FullScale buildFullScale(const MosParams& p);

// findNearestDegrees: every (degree, octave) within ±1 octave of the estimate, nearest first (stable).
struct DegreeCandidate {
  int32_t degree = 0;
  int32_t octave = 0;
  double cents = 0.0;
  double dist = 0.0;
};
std::vector<DegreeCandidate> findNearestDegrees(double targetCents, std::span<const double> pitches, int32_t n,
                                                double octave);

// updateHeldNotes semantics. A held note keeps its degree while the scale keeps its size, and so follows the scale.
// When the size changes (heldScaleSize != full.size), every note moves to the nearest free (degree, octave) slot to
// the pitch it was sounding, nearest notes first; a note with no free slot goes up an octave. heldScaleSize is the
// size the notes were last mapped against (−1 = none yet, the JS null) and is updated. currentCents is the
// unstretched pitch; nullopt means "not computed yet" (a freshly pressed note), as in the JS.
struct HeldNote {
  int32_t degree = 0;
  int32_t octave = 0;
  std::optional<double> currentCents;
};
void updateHeldNotes(std::span<HeldNote> notes, const FullScale& full, int32_t& heldScaleSize);

// buildEDOGenerators: every coprime m\n generator for n = 2..maxEdo, as cents of the period.
struct EdoGenerator {
  int32_t step = 0;
  int32_t edo = 0;
  double cents = 0.0;
};
std::vector<EdoGenerator> edoGenerators(int32_t maxEdo, double period);
// edoStepRatio: "L:s" in EDO steps when genCents sits on one of `edos` (within 0.001 cents), else nullopt.
std::optional<std::string> edoStepRatio(double genCents, int32_t mosSize, double period,
                                        std::span<const EdoGenerator> edos);

// ---- mos-calc.js (the CLI) ---------------------------------------------------------------------------------------
// The CLI has its own copies of some functions that differ from index.html (no chain-safe nudge, s = 0 for an
// equalized scale, a 4-digit hardness string). generatorForHardness exists only there and is built on them.
namespace mos_calc {

MosScale buildMosScale(double genCents, int32_t n, double period);
Hardness computeHardness(double genCents, int32_t mosSize, double period);

// getMOSRegionBounds: the first region of nL L, nS s found by the CLI's Stern–Brocot walk.
struct RegionBounds {
  double lowCents = 0.0;
  double highCents = 0.0;
  std::array<int32_t, 2> lowFrac{};   // of the period
  std::array<int32_t, 2> highFrac{};
  bool mirror = false;
};
std::optional<RegionBounds> mosRegionBounds(int32_t nL, int32_t nS, double period);

// generatorForHardness: bisection (100 rounds) for the generator with L/s = targetRatio, clamped to the region's
// minimum; outputs rounded like the JS (+toFixed(6) / +toFixed(4)).
struct HardnessSolution {
  double generator = 0.0;
  double L = 0.0;
  double s = 0.0;
  double ratio = 0.0;
};
std::optional<HardnessSolution> generatorForHardness(int32_t nL, int32_t nS, double targetRatio, double period);

}  // namespace mos_calc

}  // namespace pq::tuning
